INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-boys-formals-shoes-wv522-white', 'Kids School Shoes - WV522 White', 'WALKAROO', 'Shoes', 'The Walkaroo Kids White School Shoe is a versatile and comfortable footwear option designed for active young kids. These shoes are crafted with a focus on both style and functionality, making them ideal for everyday wear. The lightweight design ensures comfort and ease of movement throughout the day, whether your child is running around the playground or sitting in the classroom. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-ws9105-white-blue', 'Sports Shoes for Men: Running & Training', 'Walkaroo', 'Footwear', 'Shop men''s sports shoes at Walkaroo. Lightweight running, training and walking shoes with cushioned soles and breathable uppers. Order online now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-wgp53107-brown', 'Men''s Daily Wear Comfort Sandals - WGP53107 Brown', 'BOUNCEEZ', 'Sandals', 'Step into everyday comfort and modern style with the Walkaroo Men''s WGP53107 Brown Comfort Sandals. Designed for men who prefer practical footwear with a stylish finish, these sandals feature a contemporary two-strap design, a soft footbed, and a high-grip outsole. The easy slip-on construction makes them convenient for daily use, while the comfortable footbed provides a relaxed feel with every step.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casual-flip-flop-wc8711-aqua-blue', 'Walkaroo Men Casual Flip-Flop  - WC8711 Aqua Blue', 'WALKAROO', 'Slippers', 'These flip-flops from Walkaroo are typically worn as a casual wear. They have a flat sole held on the foot by a toe thong which gives you good grip. They can be worn indoors or outdoors. Match it with your pajamas, sweatpants, hoodies,etc. And with the flip flop day outfits like the long dress, denim skirt or all black denim look, plays up the colourful Flip-flops. Try to keep the look as monochromatic as possible and play with proportions i.e., flowing bottoms & tight top. Care instructions: Minimal care, no maintenance needed.', 289.0, 309.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_747c260a-256e-4e32-ae29-7f351299f01b.jpg?v=1786513253&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_747c260a-256e-4e32-ae29-7f351299f01b.jpg?v=1786513253&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
