INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('boys-clogs-wc8732-black', 'Boy''s Clogs - WC8732 Black', 'WALKAROO', 'Slippers', 'This criss-cross toe style from Walkaroo adds on a style & gives you a very good grip. The PU sole from Walkaroo makes it light weight, durable & gives a firm grip. Your boy can wear these Walkaroo pair on an ethnic occasion. Pair it with any other traditional wear or even their casual outfits. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust. Note: Kindly purchase footwear size 1/2 cm more than your kid''s foot size.', 308.0, 314.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WC8732-BLACK_57d0d8f2-e9d2-4046-a76b-36bf61e9a1ca.jpg?v=1786512735&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WC8732-BLACK_57d0d8f2-e9d2-4046-a76b-36bf61e9a1ca.jpg?v=1786512735&width=1920"]'::jsonb, 4) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
