INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-clogs-mi604-pink-purple', 'Women''s Clogs - MI604 Pink Purple', 'ME&I', 'Slippers', 'Step into easy comfort and practicality with these ME&I Ladies Pink Purple EVA Clogs. Perfect for casual wear, gardening, quick errands, and everyday tasks, these slip-on clogs are made from lightweight, waterproof EVA. A pivoting heel strap keeps your fit secure, while ventilation ports enhance breathability and speed up drying. The all-over patterned texture adds a stylish touch to these versatile, comfy clogs.
