INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-wc4483-brown', 'Men''s Daily Wear Comfort Sandals - WC4483 Brown', 'WALKAROO SPORTZ', 'Sandals', 'Step into versatile comfort and classic style with the Walkaroo Men''s Brown Daily Wear Comfort Sandals. Designed for your everyday needs, these sandals feature a durable synthetic leather upper in brown, with two broad straps and a toe post for a secure fit. Each strap is equipped with an adjustable buckle, allowing you to customize the fit for optimal comfort. Experience responsive cushioning and reliable support with the Dual Layer EVA Sole, which utilizes layers of different densities to provide both softness and durability. These slip-on sandals are perfect for casual outings, daily errands, or relaxed wear.
