INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-clogs-wc4843-light-grey', 'Men''s Clogs  - WC4843 Light Grey', 'WALKAROO', 'Slippers', 'These flip-flops from Walkaroo are typically worn as a casual wear. They have a flat sole held on the foot by a toe thong which gives you good grip. They can be worn indoors or outdoors. Match it with your pajamas, sweatpants, hoodies,etc. And with the flip flop day outfits like the long dress, denim skirt or all black denim look, plays up the colourful Flip-flops. Try to keep the look as monochromatic as possible and play with proportions i.e., flowing bottoms & tight top. Care instructions: Minimal care, no maintenance needed.', 299.0, 299.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WC4843-LIGHTGREY-GENTS-1.jpg?v=1786513496&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WC4843-LIGHTGREY-GENTS-1.jpg?v=1786513496&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
