INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-wgp53032-olive', 'Men''s Daily Wear Comfort Sandals - WGP53032 Olive', 'BOUNCEEZ', 'Sandals', 'Step into superior comfort and versatile style with these Men''s Olive Comfort Sandals. Designed for all-day wear, these sandals feature a premium finish suede-like synthetic upper in a versatile olive color that effortlessly complements a wide range of casual and outdoor outfits. The partially closed toe design offers added protection while maintaining breathability. Achieving the perfect fit is effortless with the fully adjustable straps across the forefoot , all secured by convenient hook-and-loop fasteners (Velcro).
