INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('boys-daily-wear-sandals-wgp53410-tan', 'Boy''s Daily Wear Sandals - WGP53410 Tan', 'URBANOZ', 'Sandals', 'Experience everyday comfort and modern casual style with the Walkaroo Urbanoz WGP53410 Tan Boys Sandals. Designed for boys who need comfortable and versatile footwear for daily activities, these sandals combine a stylish dual-strap design, adjustable fit, and cushioned comfort. Ideal for daily wear, school holidays, family outings, travel, and casual outdoor activities, they offer a practical blend of comfort and style.
