INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgr53512-black', 'Men''s Daily Wear Sandals - WGR53512 Black', 'WALKAROO', 'Sandals', 'Step into modern style and exceptional comfort with the Walkaroo Men''s WGR53512 Black Daily Wear Sandal. This sandal is designed for men seeking a stylish, comfortable, and practical option for everyday wear, featuring a cushioned sole for enhanced comfort throughout the day.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-bx2554-burgandy', 'Women''s Daily Wear Sandals - BX2554 Burgundy', 'WALKAROO', 'Sandals', 'Step into effortless comfort and modern everyday style with the Walkaroo Basix Ladies Daily Wear Sandal BX2554 in Burgundy. Designed for women who want easy slip-on comfort, dependable support, and a refined daily wear look, this sandal is a practical choice for regular use, casual outings, shopping, and relaxed everyday movement.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-w1030-blue', 'Men''s Daily Wear Sandals - W1030 Blue', 'WALKAROO', 'Sandals', 'Our PU Sandal Footwear where style meets comfort. Crafted with high-quality polyurethane material, these sandals offer a perfect blend of durability and fashion. The sleek design and versatile color options make them an ideal choice for various occasions, from casual outings to more refined settings. The PU construction ensures a lightweight feel, allowing you to move with ease. Whether you''re strolling through the city or enjoying a day at the beach, these sandals provide the perfect combination of style and comfort for your every step.', 284.0, 327.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_ff3f277e-5d7a-486e-9c97-820631fbe98e.jpg?v=1786513425&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_ff3f277e-5d7a-486e-9c97-820631fbe98e.jpg?v=1786513425&width=1920"]'::jsonb, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
