INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-ws9511-navy-blue', 'Walkaroo Men Lace-up Training Shoes - WS9511 Navy Blue', 'WALKAROO', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 842.0, 999.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_706a9eb8-e8f7-4941-acf6-e0d78febb70a.jpg?v=1786513814&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_706a9eb8-e8f7-4941-acf6-e0d78febb70a.jpg?v=1786513814&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-sports-sandal-wkr81001-purple-beige', 'Kid''s Sports Sandal - WKR81001 Purple Beige', 'WALKAROO', 'Sandals', 'Let your little ones explore in comfort with our kids'' daily wear sandals. Designed to be lightweight, these sandals won''t weigh them down during playtime. The durable construction ensures they can withstand everyday adventures, while the buckle adjustment provides a secure and customizable fit. Perfect for casual outings and everyday wear, these sandals are a reliable choice for active kids', 242.0, 261.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WKR81001-PURPLEBEIGE-KIDS_d5fe1f55-60fc-4678-b3b1-68dbe1a9368b.jpg?v=1786512145&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WKR81001-PURPLEBEIGE-KIDS_d5fe1f55-60fc-4678-b3b1-68dbe1a9368b.jpg?v=1786512145&width=1920"]'::jsonb, 6) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
