INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-13505-black', 'Men''s Fisherman Sandals - 13505 Black', 'WALKAROO', 'SANDALS', 'These sandal from Walkaroo with closed toes is perhaps one of the best options if youâ€šre looking for somewhat a hybrid, a type of shoe crossed with a sandal. The benefit is that they give you all the support of a standard pair of shoes, but also the breathability of sandals.These sandals from Walkaroo provides maximum coverage and it is perfect for your ethnic wear & smart casuals. Pair it with your trousers, chinos or any other smart casuals. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust.', 419.0, 529.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_115074fb-8a46-4987-b486-2cf1168053ca.jpg?v=1786511353&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_115074fb-8a46-4987-b486-2cf1168053ca.jpg?v=1786511353&width=1920"]'::jsonb, 8) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
