INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-formal-shoes-wf6301-black', 'Men''s Formal Shoes - WF6301 Black', 'WALKAROO', 'Shoes', 'This style from Walkaroo is a quick wear, easy to take on and off. You can wear them for formals & also smart casuals. Being easy to dress up or down makes these the newest go-to shoe.  You can pair this brown formal shoe with a black, dark brown, blue or grey suit. You can pair these Walkaroo shoes even with your jeans, chinos, smart casual outfits and other formal looks.  Care Instruction: Use a dry brush to remove any dust and dirt from the shoes & polish the shoe according to your preference.', 795.0, 849.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/3_2b14f5a7-8cb2-4d47-9928-df967c6e9ebd.jpg?v=1786512908&width=1920', '["https://www.walkaroo.in/cdn/shop/files/3_2b14f5a7-8cb2-4d47-9928-df967c6e9ebd.jpg?v=1786512908&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
