INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandal-wlr70401-brown', 'Women''s Daily wear Sandal - WLR70401 Brown', 'WALKAROO', 'Slippers', 'Step into effortless style and comfort with the Walkaroo Women''s WLR70401 Brown Daily Wear Sandals. Designed as your go-to footwear for everyday ease, these lightweight sandals offer a perfect blend of classic elegance and enduring comfort.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-boys-sandals-w1030-black', 'Walkaroo Boys Sandals  - W1030 Black', 'WALKAROO', 'Sandals', 'The sole is held on your foot by a toe Thongwhich gives you good grip. The PU sole from Walkaroo makes it light weight, durable & gives a firm grip. You can wear these Walkaroo pair on your ethnic occasion. Pair it with your Dhoti or any other traditional wear. Care instruction: Minimal care, no maintenance needed.', 159.0, 269.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/W1030_kids_4a95ac0a-4ba3-48eb-8e97-3ee12e3158c0.jpg?v=1786512777&width=1920', '["https://www.walkaroo.in/cdn/shop/files/W1030_kids_4a95ac0a-4ba3-48eb-8e97-3ee12e3158c0.jpg?v=1786512777&width=1920"]'::jsonb, 11) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
