INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('daytona-v2-convertible-bike-saddle-bag-trekking-bag', 'Daytona V2 | (Convertible) Bike Saddle Bag/Trekking Bag', 'Walkaroo', 'Footwear', 'Get the Strabo Daytona bike saddle bag for hassle-free weekend and long rides. This versatile bag works as a saddle bag for your bike and a trekking bag when you stop. It keeps your valuables secure and adds style to your gear. Don''t carry multiple bags, get the ease of use you need with Strabo Daytona.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wlp72046-black', 'Women''s Daily Wear Sandals - WLP72046 Black', 'WALKAROO PLUS', 'Sandals', 'Step into everyday comfort and stylish simplicity with the Walkaroo Women’s WLP72046 Black Daily Wear Sandal. Designed for women who want practical comfort, modern styling, and easy daily wear, this sandal is a dependable choice for regular use, casual outings, and day-to-day movement.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-clogs-wk388-beige-pink', 'Kid''s Clogs  - WK388 Beige Pink', 'WALKAROO', 'Slippers', 'Step into playful comfort and standout style with the Walkaroo Kids'' WK388 Beige Pink Clogs. This pair distinguishes itself from regular kids’ clogs through its delightful colours, fun **design**, and all-day comfort — perfect for little feet that never stop exploring.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-wgr53350-black', 'Men''s Daily Wear Comfort Sandals - WGR53350 Black', 'BOUNCEEZ', 'Sandals', 'Walkaroo Bounceez WGR53350 in Black is a men’s slip-on comfort sandal designed for easy everyday wear, adjustable fitting, and relaxed walking comfort. Featuring a two-strap adjustable design, a soft cushioned footbed, and water-resistant construction, this pair is a practical choice for daily use, casual outings, travel, errands, and regular home-to-outdoor wear.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-w187-blue', 'Women''s Daily Wear Sandals - W187 Blue', 'WALKAROO', 'Sandals', 'Meet the Walkaroo W187, a lightweight women’s toe-post sandal that balances everyday comfort with a chic two-tone strap look. The secure toe thong keeps your foot in place while the PU sole feels light, durable, and offers a firm grip. Style it effortlessly with casuals and ethnics—skirts, salwar kameez, kurtas, and tops.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-mens-clogs-wc8712-white', 'Clogs for Men – EVA Clogs & Slippers ₹249+', 'Walkaroo', 'Footwear', 'Shop men''s clogs that are water-friendly, lightweight & easy to clean. Starting ₹249. Made in India. Free shipping & COD available.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandal-wlr74019-dusty-rose', 'Women''s Daily Wear Sandal  - WLR74019 Dusty Rose', 'WALKAROO', 'Sandals', 'Step into ultimate comfort and style with the Walkaroo Women''s Daily Wear Sandals, model WLR74019. These sandals are meticulously crafted from high-quality PU and Rexine, offering a perfect blend of durability and elegance. Designed in a beautiful Dusty Rose color, these slip-on sandals, also known as women''s chappals or casual sandals, are the perfect addition to your everyday wardrobe. The soft and flexible material, combined with a contoured footbed, provides exceptional comfort and support, making them ideal for long hours of wear. Whether you''re running errands or enjoying a casual day out, these lightweight and fashionable sandals ensure your feet feel great all day long.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wlr70417-plum', 'Women''s Daily Wear Sandals  - WLR70417 Plum', 'WALKAROO', 'Sandals', 'Step into elegant simplicity and superior comfort with the Walkaroo Women''s WLR70417 Plum Daily Wear Sandal. This versatile slip-on thong sandal blends style and practicality for women who prioritise comfort and a clean, modern aesthetic.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandal-wl7251-burgundy', 'Women''s Daily Wear Sandal  - WL7251 Burgundy', 'WALKAROO CARE PLUS', 'Sandals', 'Say goodbye to tired feet with these women''s daily wear and orthopedic sandals. Designed with a lightweight PU sole, they offer excellent support and flexibility for all-day wear. The soft cushioned insole provides superior comfort, making them ideal for those who spend long hours on their feet. In a rich Burgundy color, this stylish design ensures you''ll look great no matter where you go. These sandals are the perfect choice for women who prioritize both comfort and style.
