INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgp53302-black', 'Men''s Daily Wear Sandals - WGP53302 Black', 'WALKAROO PLUS', 'Sandals', 'Walkaroo WGP53302 is a men’s black daily wear sandal designed for everyday comfort, casual style, and dependable use. Built with a synthetic leather upper in a suede-finish look, this men’s T-strap sandal combines a smart dual-tone appearance with practical comfort features for regular wear. The open toe-post construction, buckle adjustment, soft cushioned insole, and PU sole make it a reliable choice for men who want a value-for-money sandal for daily walking, errands, and casual outings.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-boys-casual-shoes-wk381-navy-blue', 'Kids Footwear Online – Shoes & Sandals ₹149+', 'Walkaroo', 'Footwear', 'Shop kids'' shoes, sandals & school footwear for boys and girls. Soft, durable & comfortable. Starting ₹149. Made in India. Free shipping & COD.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-girls-formals-shoes-wv593-white', 'Kids Slip-On school Shoe - WV593 White', 'WALKAROO', 'SCHOOL', 'Ensure your little girl''s feet are ready for every school day adventure with the WALKAROO Girls'' Slip-On School Shoes. Designed with both practicality and comfort in mind, these shoes are the perfect companion for her bustling schedule, from classroom learning to playground fun. Crafted to be exceptionally lasting and durable, they can withstand the rigors of daily wear and tear, ensuring that they remain a reliable part of her uniform throughout the school year. The sturdy construction and high-quality materials mean you won''t have to worry about constant replacements, saving you time and money. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 233.0, 275.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_dda4d245-d63c-4906-883c-69e4347bf1f2.jpg?v=1786513911&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_dda4d245-d63c-4906-883c-69e4347bf1f2.jpg?v=1786513911&width=1920"]'::jsonb, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-clogs-wc8801-light-grey', 'Men''s Clogs  - WC8801 Light Grey', 'WALKAROO', 'Slippers', 'Step into easy comfort and practicality with these Walkaroo men''s Light grey EVA clogs. Perfect for casual wear, gardening, or everyday tasks, these slip-on clogs are made from lightweight and waterproof EVA material. The pivoting heel strap provides a secure fit, while the ventilation holes enhance breathability and allow for quick drying. The all-over patterned texture adds a touch of style to these versatile and comfortable clogs.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-flip-flop-sliders-wc8930-dull-pink', 'Women''s Slides – Buy Slides For Women Online in India', 'Walkaroo', 'Footwear', 'Shop stylish and comfortable women''s sliders online at Walkaroo. Our women''s slides are designed for style and comfort, featuring trendy colors, a lightweight feel, and easy maintenance. Order now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandal-wl7129-blush', 'Women''s Daily Wear Sandal  - WL7129 Blush', 'WALKAROO', 'Sandals', 'The sole is held on your foot by a toe Thong which gives you good grip. The PU sole from Walkaroo makes it light weight, durable & gives a firm grip. They go along well with your casual outfits & ethnics. Pair these Walkaroo with your different length skirts, salwar kameez, kurtas, tops etc. Care instruction: Minimal care, no maintenance needed.', 299.0, 299.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_5e74dfdd-f383-429e-94ce-69b4e160c285.jpg?v=1786512673&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_5e74dfdd-f383-429e-94ce-69b4e160c285.jpg?v=1786512673&width=1920"]'::jsonb, 2) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
