INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-slip-on-walking-shoe-ws3132-navy-blue', 'Men''s Slip-on Walking Shoe - WS3132 Navy Blue', 'WALKAROO', 'Athletic Shoes', 'Step into effortless style and comfort with the Walkaroo men''s navy blue slip-on walking shoes. Designed for easy daily wear and casual walking, these shoes feature a breathable mesh upper that provides a lightweight, sock-like fit. The slip-on design with convenient pull tabs allows for quick on and off. Built with a lightweight EVA sole, they offer responsive cushioning and comfortable steps throughout your day. The sculpted sole design adds a modern touch, making these walking shoes a versatile addition to your casual wardrobe.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-plus-men-casuals-sandals-we1332-black', 'Men''s Daily Wear Sandals - WE1332 Black', 'WALKAROO PLUS', 'Sandals', 'Experience modern style and everyday comfort with the Walkaroo Men''s WE1332 Black  Daily Wear Sandal. Designed for men who prefer a stylish open sandal with secure foot hold, this pair combines a dual-tone look, cushioned sole comfort, and easy slip-on wearability for daily use.
