INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-fgp45004-khaki-olive', 'Men''s Daily Wear Sandals - FGP45004 Khaki Olive', 'FLIP-FLOPZ+', 'Sandals', 'Step into soft, adjustable comfort with the Walkaroo Flip-Flopz Plus FGP45004—a contemporary two-strap buckle slider made for everyday wear in warm Indian weather.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-w1030-black', 'Men''s Daily Wear Sandals - W1030 Black', 'WALKAROO', 'Sandals', 'Our PU Sandal Footwear where style meets comfort. Crafted with high-quality polyurethane material, these sandals offer a perfect blend of durability and fashion. The sleek design and versatile color options make them an ideal choice for various occasions, from casual outings to more refined settings. The PU construction ensures a lightweight feel, allowing you to move with ease. Whether you''re strolling through the city or enjoying a day at the beach, these sandals provide the perfect combination of style and comfort for your every step.', 284.0, 349.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_5a2e785d-f406-414a-963d-40d2ac531d7f.jpg?v=1786513423&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_5a2e785d-f406-414a-963d-40d2ac531d7f.jpg?v=1786513423&width=1920"]'::jsonb, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
