INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('boys-comfort-sandals-wgp53222-black', 'Boy''s Comfort Sandals -WGP53222 Black', 'URBANOZ', 'Sandals', 'Step into everyday comfort and practical style with the Walkaroo Urbanoz WGP53222 Black Boys'' Comfort Sandal. Designed for active boys, this sandal combines an ergonomic design, adjustable dual-strap construction, heel support, lightweight comfort, and a slip-resistant outsole for everyday use.
