INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('girls-daily-wear-sandals-wl7672-peacock-blue', 'Girl''s Daily Wear Sandals  - WL7672 Peacock Blue', 'WALKAROO', 'Sandals', 'Step into comfort and style with the Walkaroo Girl''s Peacock Blue Daily Wear Sandals. These stylish and practical slip-on sandals are the perfect choice for women who seek ease and comfort in their everyday footwear. Featuring a simple yet elegant synthetic upper with a textured, woven-like finish, these sandals provide a secure and soft fit that''s ideal for all-day wear.
