INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-wg5451-blue-grey', 'Sandals for Men - Shop Stylish Men Sandals Online in India', 'Walkaroo', 'Footwear', 'Shop premium sandals for men online starting at ₹239 at Walkaroo. Explore stylish, durable, and comfortable mens sandals, including classic and modern slip-on sandals for everyday wear.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-formals-shoes-wf6051-brown', 'Men''s Leather formals Shoes - WF6051 Brown', 'WALKAROO', 'SHOES', 'Meet our new lineup of men''s formal shoes, crafted for comfort. The new lineup of leather shoes crafted from high-quality leather offers both comfort and style. perfected for the professionals in you.Care instructions:To remove dirt or surface residue, use a soft damp cloth. Gently rub for removal. For a deeper clean, use a leather cleaner to help preserve the natural smooth oils instead of stripping them.To prevent the leather from losing suppleness over time use a wax-free leather conditioner that will nourish and restore the flexibility and suppleness of your leather goodiesLeather is a natural material, please, store your leather Shoes in a breathable, non-plastic container to prevent the growth of bacteria and mildew.', 1349.0, 1349.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/3_b9026ecd-5f75-4600-8f52-65911ead2e40.jpg?v=1786513746&width=1920', '["https://www.walkaroo.in/cdn/shop/files/3_b9026ecd-5f75-4600-8f52-65911ead2e40.jpg?v=1786513746&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-clogs-wc4843-cool-grey', 'Men''s Clogs  - WC4843 Cool Grey', 'WALKAROO', 'Slippers', 'These flip-flops from Walkaroo are typically worn as a casual wear. They have a flat sole held on the foot by a toe thong which gives you good grip. They can be worn indoors or outdoors. Match it with your pajamas, sweatpants, hoodies,etc. And with the flip flop day outfits like the long dress, denim skirt or all black denim look, plays up the colourful Flip-flops. Try to keep the look as monochromatic as possible and play with proportions i.e., flowing bottoms & tight top. Care instructions: Minimal care, no maintenance needed.', 299.0, 329.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WC4843-COOLGREY-GENTS-1_dd8b1f56-97bb-4aba-9cea-b304d9171a24.jpg?v=1786512109&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WC4843-COOLGREY-GENTS-1_dd8b1f56-97bb-4aba-9cea-b304d9171a24.jpg?v=1786512109&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('camper-2-in-1-duffel-backpack-silver', 'Camper 2-in-1 Duffel + Backpack - Grey', 'Strabo', 'Duffel Bags', 'Meet our smartly designed, accessible 2-in-1 convertible duffel bag and backpack – the ultimate travel companion. Whether you''re on vacation or running errands, this versatile bag has you covered.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-sge28007-beige', 'Men''s Daily Wear Comfort Sandals - SGE28007 Beige', 'WALKAROO SPORTZ', 'Sandals', 'Slide into everyday comfort with the Walkaroo Sportz Men’s Slip-on Sandal – SGE28007 (Beige). Designed for daily wear, this open-toe sandal combines a soft suede-finish upper with a cushioned EVA sole and a slip-resistant tread for steady steps from errands to evening strolls. Two functional metal buckles let you fine-tune the fit across the instep for all-day ease.
