INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-clogs-wc8801-cool-grey', 'Men''s Clogs  - WC8801 Cool Grey', 'WALKAROO', 'Slippers', 'Step into easy comfort and practicality with these Walkaroo men''s Cool grey EVA clogs. Perfect for casual wear, gardening, or everyday tasks, these slip-on clogs are made from lightweight and waterproof EVA material. The pivoting heel strap provides a secure fit, while the ventilation holes enhance breathability and allow for quick drying. The all-over patterned texture adds a touch of style to these versatile and comfortable clogs.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-clogs-wc8814-cool-grey', 'Men''s Clogs  -  WC8814 Cool Grey', 'WALKAROO', 'Slippers', 'Step into unparalleled comfort and standout style with the Walkaroo Men''s WC8814 Cool Grey Clogs. This pair distinguishes itself significantly from competitors through its unique colours and innovative **design**, in addition to its superior comfort and exceptional value.
