INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-daily-wear-sandals-wk728-plum', 'Kid''s Daily Wear Sandals - WK728 Plum', 'WALKAROO', 'Sandals', 'Designed for all-day play and everyday style, the Walkaroo WK728 Kid''s ’ sandal pairs a soft, cushioned sole with a secure Velcro back-strap so it’s easy on and off for little feet. The two-strap front adds a touch of sparkle with a slim metallic accent, while the lightweight build keeps every step comfy—perfect for playground runs, park strolls and weekend outings. 
