INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-clogs-wc4849-aqua', 'Walkaroo Mens Clogs  - WC4849 Aqua', 'WALKAROO', 'Slippers', 'These flip-flops from Walkaroo are typically worn as a casual wear. They have a flat sole held on the foot by a toe thong which gives you good grip. They can be worn indoors or outdoors. Match it with your pajamas, sweatpants, hoodies, etc. And with the flip flop day outfits like the long dress, denim skirt or all black denim look, plays up the colourful Flip-flops. Try to keep the look as monochromatic as possible and play with proportions i.e., flowing bottoms & tight top. Care instructions: Minimal care, no maintenance needed.', 355.0, 359.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_b54c283d-5190-4c76-a66a-ca583aa6cc46.jpg?v=1786513498&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_b54c283d-5190-4c76-a66a-ca583aa6cc46.jpg?v=1786513498&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casual-flip-flop-wc8711-greige', 'Walkaroo Men Casual Flip-Flop  - WC8711 Greige', 'WALKAROO', 'Slippers', 'These flip-flops from Walkaroo are typically worn as a casual wear. They have a flat sole held on the foot by a toe thong which gives you good grip. They can be worn indoors or outdoors. Match it with your pajamas, sweatpants, hoodies,etc. And with the flip flop day outfits like the long dress, denim skirt or all black denim look, plays up the colourful Flip-flops. Try to keep the look as monochromatic as possible and play with proportions i.e., flowing bottoms & tight top. Care instructions: Minimal care, no maintenance needed.', 289.0, 294.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_00773e6c-cc72-4e65-b716-90e5443c2be2.jpg?v=1786513201&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_00773e6c-cc72-4e65-b716-90e5443c2be2.jpg?v=1786513201&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
