INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-school-shoe-wv591-black', 'Kids School Shoe - WV591 Black', 'WALKAROO', 'SCHOOL', 'Walkaroo Girls'' School Shoes are designed to keep up with your little girl''s active lifestyle and provide comfort and support throughout the school day. These shoes are built to last, featuring a lasting and durable construction that can withstand the daily wear and tear of a busy school schedule. Made with quality materials, they''ll remain a dependable part of her uniform throughout the year.', 209.0, 280.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_732bc333-b9a8-440f-ac6a-00be79f5461f.jpg?v=1786512173&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_732bc333-b9a8-440f-ac6a-00be79f5461f.jpg?v=1786512173&width=1920"]'::jsonb, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
