INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-wgr53350-brown', 'Men''s Daily Wear Comfort Sandals - WGR53350 Brown', 'BOUNCEEZ', 'Sandals', 'Walkaroo Bounceez WGR53350 in Brown is a men’s slip-on comfort sandal designed for easy everyday wear, adjustable fitting, and relaxed walking comfort. Featuring a two-strap adjustable design, a soft cushioned footbed, and water-resistant construction, this pair is a practical choice for daily use, casual outings, travel, errands, and regular home-to-outdoor wear.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wlp72046-brown', 'Women''s Daily Wear Sandals - WLP72046 Brown', 'WALKAROO PLUS', 'Sandals', 'Step into everyday comfort and stylish simplicity with the Walkaroo Women’s WLP72046 Brown Daily Wear Sandal. Designed for women who want practical comfort, modern styling, and easy daily wear, this sandal is a dependable choice for regular use, casual outings, and day-to-day movement.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-slip-on-sports-shoe-ong97011-dark-grey', 'Men''s Slip-On Sports Shoe -ONG97011 Dark Grey', 'WALKAROO SPORTZ', 'Athletic Shoes', 'Step into effortless comfort and modern performance with the Walkaroo Sportz ONG97011 Dark Grey Slip-On Shoes. Designed for men who prefer convenience without compromising on style, this slip-on sports shoe features a sleek all-Dark Grey design with a breathable knit/mesh upper that delivers a snug, sock-like fit. Perfect for daily wear, walking, travel, and light activities, it blends functionality with a sporty aesthetic.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-kids-clogs-wk358-white-red', 'Kid''s Clogs  - WK358 White Red', 'WALKAROO', 'Slippers', 'These comfy clogs from Walkaroo are perfect for your kid''s active lifestyle. Made from lightweight EVA material, they''re super easy to slip on and off and won''t weigh your little one down. The soft and squishy insoles provide all-day comfort, while the sturdy soles offer great grip on any surface. With their fun and colorful designs, these clogs are sure to become your child''s go-to shoes for playtime, school, or any adventure', 233.0, 249.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WK358-WHITERED-KIDS_68ef39de-f378-466e-939c-d9722d6f73cd.jpg?v=1786512501&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WK358-WHITERED-KIDS_68ef39de-f378-466e-939c-d9722d6f73cd.jpg?v=1786512501&width=1920"]'::jsonb, 4) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-comfort-sandals-wlp74021-dusty-rose', 'Women''s Daily Wear Comfort Sandals  - WLP74021 Dusty Rose', 'CLASSICO', 'Sandals', 'Step into effortless style and comfort with the Walkaroo Women''s WLP74021 Dusty  Rose Daily Wear Sandal. Designed for the modern woman, this sandal embodies a perfect blend of everyday style, exceptional comfort, and remarkable value, making it an indispensable part of your daily footwear collection.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-kids-casual-shoes-wk335-navy-blue', 'Kids Footwear Online – Shoes & Sandals ₹149+ – Page 2', 'Walkaroo', 'Footwear', 'Shop kids'' shoes, sandals & school footwear for boys and girls. Soft, durable & comfortable. Starting ₹149. Made in India. Free shipping & COD.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('girls-daily-wear-sandals-wk760-blue', 'Girl''s Daily Wear Sandals  - WK760 Blue', 'WALKAROO', 'Sandals', 'The sling back sandals from Walkaroo with elastic closure provides firm grip on the feet. This is easy to wear & take off. These are the perfect footwear for any day and will compliment a pretty dress, fluffy skirts or a funky pair of shorts. You can Mix and Match this Walkaroo pair with any of their casual wears. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust. Note: Kindly purchase footwear size 1/2 cm more than your kid''s foot size.', 209.0, 244.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WK760-BLUE_15440b3e-4256-45e0-9ee5-212f7b005c46.jpg?v=1786512910&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WK760-BLUE_15440b3e-4256-45e0-9ee5-212f7b005c46.jpg?v=1786512910&width=1920"]'::jsonb, 6) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
