INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-kids-casuals-sandals-wk799-blue-orange', 'Walkaroo Kids Cartoonic Thong Sandals  - WK799 Blue Orange', 'WALKAROO', 'SANDALS', 'The sole is held on your foot by a toe thong which gives you good grip. The PU sole from Walkaroo makes it light weight, durable & gives a firm grip. Your boy can wear these Walkaroo pair on an ethnic occasion. Pair it with any other traditional wear or even their casual outfits. Care instruction: Minimal care, no maintenance needed. Note: Kindly purchase footwear size 1/2 cm more than your kid''s foot size.', 191.0, 224.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_59e01ab3-6af8-448b-9778-d005e3b760d0.jpg?v=1786513144&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_59e01ab3-6af8-448b-9778-d005e3b760d0.jpg?v=1786513144&width=1920"]'::jsonb, 6) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
