INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-formals-shoes-wf6012-black', 'Walkaroo - Men''s, Women''s & Kid''s Footwear | India''s No.1 PU Brand', 'Walkaroo', 'Footwear', 'Buy footwear online from India''s No.1 PU footwear brand at an affordable price. Walkaroo offers a wide range of footwear for Men, Women, and Kids, including shoes, flip-flops, sandals, sliders, heels, and flats. Shop now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('men-sports-sandals-wgp58090-black', 'Men Sports Sandals - WGP58090 Black', 'WALKAROO PLUS', 'SANDALS', 'Step into comfort and everyday style with the Walkaroo Men''s WGP58090 Black Sports Sandal. Designed for men who prefer a secure fit, cushioned comfort, and versatile casual styling, this sandal is suitable for daily wear, walking, travel, shopping, errands, and relaxed outdoor activities.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-girls-formals-shoes-wv552-black', 'Girls School Shoe -WV552 Black', 'WALKAROO', 'SCHOOL', 'The WALKAROO Girls'' School Shoe is designed for the active school day, combining essential features into a reliable and comfortable option. These shoes are remarkably lightweight, ensuring your child can move freely and comfortably from classroom to playground. Built with durability in mind, they withstand the daily wear and tear of a busy school schedule, providing long-lasting use. The convenient Velcro strap closure allows for easy on and off, promoting independence and saving valuable time during hectic mornings. With these key features, WALKAROO provides a practical and comfortable school shoe that supports your child throughout their day Care Instruction: Use a dry brush to remove any dust and dirt from the shoes &amp; polish the shoe according to your preference.', 308.0, 329.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/03_e4eca613-6891-4c45-bb8c-eedc19fb3227.jpg?v=1786513913&width=1920', '["https://www.walkaroo.in/cdn/shop/files/03_e4eca613-6891-4c45-bb8c-eedc19fb3227.jpg?v=1786513913&width=1920"]'::jsonb, 3) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
