INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-ws9541-teal', 'Sports Shoes for Men: Running & Training', 'Walkaroo', 'Footwear', 'Shop men''s sports shoes at Walkaroo. Lightweight running, training and walking shoes with cushioned soles and breathable uppers. Order online now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-chelsea-boots-wge26702-black', 'Men''s Chelsea Boots - WGE26702 Black', 'WALKAROO PLUS', 'Shoes', 'Elevate your formal and smart casual style with Walkaroo WGE26702 Black Boots  - men’s black formal ankle boots designed for a sharp look, comfortable fit, and everyday versatility. The convenient zip-type closure makes them easy to wear and remove, while the smooth synthetic leather finish gives them a polished appearance for office wear, business meetings, parties, and smart casual outfits.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgr53179-olive', 'Men''s Daily Wear Sandals - WGR53179 Olive', 'WALKAROO', 'Sandals', 'Step into the ultimate blend of comfort and rugged style with the Walkaroo Men''s Olive Daily Wear Sandals. Designed for the dynamic man, these sandals offer a secure fit and a powerful look, making them an ideal choice for any casual adventure. The sleek olive color and robust design are complemented by a focus on superior foot comfort.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sandals-we1333-beige', 'Sandals for Men - Shop Stylish Men Sandals Online in India', 'Walkaroo', 'Footwear', 'Shop premium sandals for men online starting at ₹239 at Walkaroo. Explore stylish, durable, and comfortable mens sandals, including classic and modern slip-on sandals for everyday wear.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wg5661-black-tan', 'Men''s Daily Wear Sandals  - WG5661 Black Tan', 'WALKAROO', 'Sandals', 'Slide into all-day ease with the Walkaroo WG5661 in a versatile Black–Tan dual tone. The two adjustable cross straps with metal buckles let you customize the fit, while the lightweight PU sole and a softly cushioned footbed keep every step comfortable and steady. Dress them up with ethnic wear (dhoti, kurta sets) or keep it casual with chinos and denim.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-kids-casual-shoes-571-navy-blue', 'Kids Footwear Online – Shoes & Sandals ₹149+ – Page 2', 'Walkaroo', 'Footwear', 'Shop kids'' shoes, sandals & school footwear for boys and girls. Soft, durable & comfortable. Starting ₹149. Made in India. Free shipping & COD.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
