INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-we1337-blue', 'Men''s Daily Wear Comfort Sandals - WE1337 Blue', 'BOUNCEEZ', 'Sandals', 'Elevate your ethnic style with the Walkaroo WE1337 Men''s Sandals in Blue thoughtfully crafted for comfort, durability, and traditional charm. These men''s toe ring sandals for dhoti feature a sturdy PU sole for slip resistance and all-day wearability. The secure toe loop design offers a traditional touch, making them perfect for pairing with kurta-pyjama, dhoti, or sherwani during weddings and festivals.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-flip-flops-wc4819-black', 'Walkaroo - Men''s, Women''s & Kid''s Footwear | India''s No.1 PU Brand', 'Walkaroo', 'Footwear', 'Buy footwear online from India''s No.1 PU footwear brand at an affordable price. Walkaroo offers a wide range of footwear for Men, Women, and Kids, including shoes, flip-flops, sandals, sliders, heels, and flats. Shop now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-comfort-sandals-wlp72051-cream', 'Women''s Daily Wear Comfort Sandals  - WLP72051 Cream', 'CLASSICO', 'Sandals', 'Meet the Walkaroo Classico Women’s Cross-Strap Platform Sandal (WLP72051) in a soft, stylish Cream—made to look elegant and feel easy from morning to night. With a synthetic leather upper, a cushioned PU footbed, and a durable PU sole with slip-resistant grip, this slip-on sandal is built for daily wear, office comfort, casual outings, and travel.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-comfort-sandals-we2200-brown', 'Women''s Daily Wear Comfort Sandals - WE2200 Brown', 'BOUNCEEZ', 'Sandals', 'Step into all-day comfort with WALKAROO Double-Density PU Sandals – the perfect blend of style and support. Designed for casual wear, these women’s sandals feature a double-density polyurethane sole that provides superior cushioning and shock absorption, ensuring your feet stay comfortable from morning to night. The softer inner layer offers a plush feel, while the firmer outer layer delivers stability and durability. Whether you''re strolling through the park or heading out for a casual outing, these sandals are built to keep you feeling light on your feet without compromising on style. Perfect for those who want comfort, durability, and a touch of elegance in their everyday footwear.', 549.0, 549.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_3b5c9f8c-90ea-4868-9777-9771c7401106.jpg?v=1753513219&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_3b5c9f8c-90ea-4868-9777-9771c7401106.jpg?v=1753513219&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
