INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sandals-we1356-black', 'Men''s Daily Wear Comfort Sandals - WE1356 Black', 'BOUNCEEZ', 'Sandals', 'Looking for the perfect pair of men''s black sandals for daily use that also complement your traditional outfits? The Walkaroo WE1356 is designed just for that. The sole is securely held on your foot by a toe thong, offering excellent grip and comfort throughout the day.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('camper-2-in-1-convertible-duffel-bag-plus-backpack-55-liter-navy-blue', 'Camper 2-in-1 Duffel + Backpack - Navy Blue', 'Strabo', 'Duffel Bags', 'Meet our smartly designed, accessible 2-in-1 convertible duffel bag and backpack – the ultimate travel companion. Whether you''re on vacation or running errands, this versatile bag has you covered.
