INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-flip-flops-fgr41706-black-grey', 'Men''s Flip Flops- FGR41706 Black Grey', 'WALKAROO', 'Slippers', 'Step into relaxed everyday comfort with the Walkaroo FGR41706 Black Grey Flip-Flop. Designed for men who prefer easy-to-wear casual footwear, this lightweight flip-flop for men combines a soft underfoot feel with a rugged outdoor-inspired look for daily use, travel, errands, and casual outings.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-mens-clogs-wc4843-white', 'Men''s Clogs  - WC4843 White', 'WALKAROO', 'Slippers', 'These flip-flops from Walkaroo are typically worn as a casual wear. They have a flat sole held on the foot by a toe thong which gives you good grip. They can be worn indoors or outdoors. Match it with your pajamas, sweatpants, hoodies,etc. And with the flip flop day outfits like the long dress, denim skirt or all black denim look, plays up the colourful Flip-flops. Try to keep the look as monochromatic as possible and play with proportions i.e., flowing bottoms & tight top. Care instructions: Minimal care, no maintenance needed.', 299.0, 299.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WC4843-WHITE-GENTS_8c30c8a5-f283-4ba8-9ed6-84fae96a723a.jpg?v=1786513084&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WC4843-WHITE-GENTS_8c30c8a5-f283-4ba8-9ed6-84fae96a723a.jpg?v=1786513084&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wlr72052-espresso', 'Women''s Daily Wear Sandals - WLR72052 Espresso', 'WALKAROO', 'Sandals', 'WALKAROO Women’s Daily Wear Sandals (WLR72052) in Espresso are designed for everyday comfort with a stylish modern look. Featuring an easy slip-on design, a soft cushion sole, and a durable PU sole, these sandals are ideal for daily wear—whether you are running errands, heading out casually, travelling, or moving through your day in comfort.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-wg5060-black', 'Men''s Daily Wear Sandals  - WG5060 Black', 'WALKAROO', 'Sandals', 'Enjoy everyday comfort and simple casual style with the Walkaroo Men''s WG5060 Daily Wear Slipper. Designed for men who prefer lightweight and easy-to-wear footwear, this slipper combines a soft cushioned footbed, stylish broad strap design, and durable PU sole construction for regular daily use.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-w5687-brown', 'Men''s Daily Wear Sandals  - W5687 Brown', 'WALKAROO', 'Sandals', 'Step into everyday comfort with the Walkaroo W5687 in Brown — a lightweight, open-toe sandal featuring a secure criss-cross toe style and a durable PU sole. The ribbed straps and textured footbed provide a firm, anti-slip grip so you stay confident on the move. Ideal for daily wear and ethnic occasions alike — pair it with your dhoti, kurta sets, or casuals.
