INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-we8821-black', 'Men''s Daily Wear Sandals - WE8821 Black', 'FLIP-FLOPZ+', 'Sandals', 'Step into the perfect blend of comfort, style, and adjustability with the Walkaroo Men''s WE8821 Black Sandal. Designed for casual daily wear, this contemporary sandal promises "All Day Comfort" and an exceptionally "SOFT" feel . It''s your ideal companion for relaxed outings, offering both "Street Fun" and an "On Trend" look .
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sandals-we1337-tan', 'Men''s Daily Wear Comfort Sandals - WE1337 Tan', 'BOUNCEEZ', 'Sandals', 'Elevate your ethnic style with the Walkaroo WE1337 Men''s Sandals in WE1337 , thoughtfully crafted for comfort, durability, and traditional charm. These men''s toe ring sandals for dhoti feature a sturdy PU sole for slip resistance and all-day wearability. The secure toe loop design offers a traditional touch, making them perfect for pairing with kurta-pyjama, dhoti, or sherwani during weddings and festivals.
