INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('girls-school-shoes-wv592-white', 'Girls School Shoes - WV592 White', 'WALKAROO', 'SCHOOL', 'The Walkaroo Girls'' School Shoes are designed to keep pace with your little one''s active lifestyle. These shoes are built to last, boasting a lasting and durable construction that can withstand the daily wear and tear of a busy school day. The convenient Velcro strap closure makes them easy to put on and take off, promoting independence and saving precious time. Parents will appreciate the low maintenance nature of these shoes, requiring only a quick wipe for cleaning. Designed for everyday activities, they provide comfort and support for all her school adventures. Trust Walkaroo to provide quality and comfort for your child''s school footwear.', 317.0, 317.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_a8efbfcf-d835-44de-85bd-b698d8355f6d.jpg?v=1786512175&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_a8efbfcf-d835-44de-85bd-b698d8355f6d.jpg?v=1786512175&width=1920"]'::jsonb, 6) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
