INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-boys-casuals-sandals-wk360-navy-blue-yellow', 'Walkaroo Boys Sandals Footwear  - WK360 Navy Blue Yellow', 'WALKAROO', 'Slippers', 'This criss-cross toe style from Walkaroo adds on a style & gives you a very good grip. The PU sole from Walkaroo makes it light weight, durable & gives a firm grip. Your boy can wear these Walkaroo pair on an ethnic occasion. Pair it with any other traditional wear or even their casual outfits. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust. Note: Kindly purchase footwear size 1/2 cm more than your kid''s foot size.', 299.0, 319.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_21257901-7f74-459a-92b3-121cc9bcdcd6.jpg?v=1786513335&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_21257901-7f74-459a-92b3-121cc9bcdcd6.jpg?v=1786513335&width=1920"]'::jsonb, 4) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
