INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-clogs-wc4843-greige', 'Men''s Clogs  - WC4843 Greige', 'WALKAROO', 'Slippers', 'Step into soft comfort and easy everyday style with the Walkaroo Men''s WC4843 Greige Clogs. Designed for daily wear, casual outings, home use, errands, and relaxed outdoor activities, these clogs offer a lightweight feel, breathable design, and all-day easy wearability.
