INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-lace-up-sports-shoe-ws3083-grey', 'Men''s Lace-up Sports Shoes - WS3083 Grey', 'WALKAROO', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 683.0, 699.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_de1bf276-e440-4ef0-b1e6-de2762c285bc.jpg?v=1786512430&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_de1bf276-e440-4ef0-b1e6-de2762c285bc.jpg?v=1786512430&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-wgp53032-camel', 'Men''s Daily Wear Comfort Sandals - WGP53032 Camel', 'BOUNCEEZ', 'Sandals', 'Step into superior comfort and versatile style with these Men''s Camel Comfort Sandals. Designed for all-day wear, these sandals feature a premium finish suede-like synthetic upper in a versatile Camel color that effortlessly complements a wide range of casual and outdoor outfits. The partially closed toe design offers added protection while maintaining breathability. Achieving the perfect fit is effortless with the fully adjustable straps across the forefoot , all secured by convenient hook-and-loop fasteners (Velcro).
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-we8822-khaki-tan', 'Men''s Daily Wear Sandals - WE8822 Khaki Tan', 'FLIP-FLOPZ+', 'Sandals', 'Step into unparalleled comfort, durability, and style with the Walkaroo Men''s Khaki Tan Floater Sandals with Adjustable Buckles. Designed for the modern Indian man with an active lifestyle, these sandals effortlessly combine the best price with good quality, making them an essential addition to your everyday and outdoor footwear collection.
