INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-sge28005-olive', 'Men''s Daily Wear Comfort Sandals - SGE28005 Olive', 'WALKAROO SPORTZ', 'Sandals', 'Slide into everyday comfort with the Walkaroo Sportz Men’s Double‑Buckle Sandal – SGE28005 (Olive). Designed for daily wear, this open‑toe sandal combines a soft suede‑finish upper with a cushioned EVA sole and a slip‑resistant tread for steady steps from errands to evening strolls. Two functional metal buckles let you fine‑tune the fit across the instep for all‑day ease.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-walking-shoes-ws9584-navy-blue', 'Sports Shoes for Men: Running & Training', 'Walkaroo', 'Footwear', 'Shop men''s sports shoes at Walkaroo. Lightweight running, training and walking shoes with cushioned soles and breathable uppers. Order online now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-slip-on-waterproof-shoes-wc4703-brown', 'Men''s Slip-On Rain Shoes - WC4703 Brown', 'WALKAROO', 'Shoes', 'The perfect blend of comfort and style with our men''s PVC slip-on shoes. Crafted from durable PVC material, these shoes offer exceptional water resistance and easy maintenance. The slip-on design makes them effortless to put on and take off, making them ideal for casual outings and everyday wear.', 284.0, 309.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/3_69fec8f6-45e4-4952-82d1-12302e85b5ee.jpg?v=1786512749&width=1920', '["https://www.walkaroo.in/cdn/shop/files/3_69fec8f6-45e4-4952-82d1-12302e85b5ee.jpg?v=1786512749&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
