INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandal-wlr74019-plum', 'Women''s Daily Wear Sandal  - WLR74019 Plum', 'WALKAROO', 'Sandals', 'Step into ultimate comfort and style with the Walkaroo Women''s Daily Wear Sandals, model WLR74019. These sandals are meticulously crafted from high-quality PU and Rexine, offering a perfect blend of durability and elegance. Designed in a beautiful Plum shade, these slip-on sandals—also known as women''s chappals or casual sandals—are the perfect addition to your everyday wardrobe. The soft and flexible material, combined with a contoured footbed, provides exceptional comfort and support, making them ideal for long hours of wear. Whether you''re running errands or enjoying a casual day out, these lightweight and fashionable sandals ensure your feet feel great all day long.
