INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('boys-clogs-wc8732-white', 'Boy''s Clogs - WC8732 White', 'WALKAROO', 'Slippers', 'This criss-cross toe style from Walkaroo adds on a style & gives you a very good grip. The PU sole from Walkaroo makes it light weight, durable & gives a firm grip. Your boy can wear these Walkaroo pair on an ethnic occasion. Pair it with any other traditional wear or even their casual outfits. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust. Note: Kindly purchase footwear size 1/2 cm more than your kid''s foot size.', 308.0, 314.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WC8732-WHITE_ec7d157d-7415-4d45-891d-c89bd74df053.jpg?v=1786512736&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WC8732-WHITE_ec7d157d-7415-4d45-891d-c89bd74df053.jpg?v=1786512736&width=1920"]'::jsonb, 4) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-women-casuals-sandals-bt2702-peach', 'Blue Tyga Womens Ankle Strap Flat Sandals  - BT2702 Peach', 'BLUE TYGA', 'Sandals', 'The sling back sandals from Walkaroo with elastic closure provides firm grip on your feet. This is easy to wear & take off.   You can pair these Walkaroo with your salwar, kurtas, saree, skirts etc. And wear it on a casual, ethnic occasions or even as an everyday outdoor sandals.  Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust.', 280.0, 299.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/bt2702-peach_5__1_1_31976939-aaf6-4213-b658-1f72df296c1d.jpg?v=1786513321&width=1920', '["https://www.walkaroo.in/cdn/shop/files/bt2702-peach_5__1_1_31976939-aaf6-4213-b658-1f72df296c1d.jpg?v=1786513321&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
