INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-comfort-sandals-we2501-olive', 'Women''s Daily Wear Comfort Sandals - WE2501 OLIVE', 'BOUNCEEZ', 'Sandals', 'Step into all-day comfort with WALKAROO Double-Density PU Sandals – the perfect blend of style and support. Designed for casual wear, these women’s sandals feature a double-density polyurethane sole that provides superior cushioning and shock absorption, ensuring your feet stay comfortable from morning to night. The softer inner layer offers a plush feel, while the firmer outer layer delivers stability and durability. Whether you''re strolling through the park or heading out for a casual outing, these sandals are built to keep you feeling light on your feet without compromising on style. Perfect for those who want comfort, durability, and a touch of elegance in their everyday footwear.', 539.0, 559.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_548fbf70-f873-4a51-8b88-5cc7f5ab0fc0.jpg?v=1753514719&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_548fbf70-f873-4a51-8b88-5cc7f5ab0fc0.jpg?v=1753514719&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
