INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-we2362-black-beige', 'Women''s Daily Wear Sandals - WE2362 Black Beige', 'WALKAROO PLUS', 'Sandals', 'Enjoy everyday style and soft walking comfort with the Walkaroo Women''s WE2362 Daily Wear Sandal. Designed for women who prefer easy slip-on footwear with a stylish look, this sandal combines a double buckle upper, cushioned sole feel, and lightweight PU construction for regular use.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-clogs-mi604-light-grey', 'Women''s Clogs - MI604 Light Grey', 'ME&I', 'Slippers', 'Step into easy comfort and practicality with these ME&I Ladies Light Grey EVA Clogs. Perfect for casual wear, gardening, quick errands, and everyday tasks, these slip-on clogs are made from lightweight, waterproof EVA. A pivoting heel strap keeps your fit secure, while ventilation ports enhance breathability and speed up drying. The all-over patterned texture adds a stylish touch to these versatile, comfy clogs.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-kids-sports-shoes-wk340-navy-blue', 'Walkaroo Kids Pull-on Sock Shoes - WK340 Navy Blue', 'WALKAROO', 'Sneakers', 'The upper material of these Walkaroo sock shoes is stretchable hence it takes the shape of your feet. With the elastic shoe mouth design, this pair of sneakers will better fit your ankle. Due to its breathability its a perfect choice for sweaty feet. You can pair them with any of your casual wear. And these Walkaroo shoes are great to be worn at the gym, workout or dance studio. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 327.0, 327.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_0367bffb-58eb-4e94-a152-71bcbfe893a2.jpg?v=1786513120&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_0367bffb-58eb-4e94-a152-71bcbfe893a2.jpg?v=1786513120&width=1920"]'::jsonb, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
