INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-clogs-wc8922-light-grey', 'Kid''s Clogs  - WC8922 Light Grey', 'WALKAROO', 'Slippers', 'These comfy clogs from Walkaroo are perfect for your kid''s active lifestyle. Made from lightweight EVA material, they''re super easy to slip on and off and won''t weigh your little one down. The soft and squishy insoles provide all-day comfort, while the sturdy soles offer great grip on any surface. With their fun and colorful designs, these clogs are sure to become your child''s go-to shoes for playtime, school, or any adventure', 233.0, 264.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WC8922-LIGHTGREY-KIDS_5a10c324-b422-466f-84e6-b7a152b4520a.jpg?v=1786512569&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WC8922-LIGHTGREY-KIDS_5a10c324-b422-466f-84e6-b7a152b4520a.jpg?v=1786512569&width=1920"]'::jsonb, 6) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
