INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-wg5306-black', 'Men''s Fisherman Sandals  - WG5306 Black', 'WALKAROO', 'Sandals', 'These sandals from Walkaroo with closed toes is perhaps one of the best options if you are looking for somewhat a hybrid, a type of shoe crossed with a sandal. The benefit is that they give you all the support of a standard pair of shoes, but also the breathability of sandals. These sandals from Walkaroo provides maximum coverage and it is perfect for your ethnic wear & smart casuals. Pair it with your trousers, chinos or any other smart casuals. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust.', 379.0, 479.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_7b7f9dee-059e-49f2-bb68-040e07d318e1.jpg?v=1786513418&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_7b7f9dee-059e-49f2-bb68-040e07d318e1.jpg?v=1786513418&width=1920"]'::jsonb, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
