INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-lace-up-walking-shoe-ws9555-dark-grey', 'Men''s Lace-up Walking Shoe - WS9555 Dark Grey', 'WALKAROO', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 842.0, 899.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_71bfa4f7-6d9b-4e88-ab5e-1cdbc4707898.jpg?v=1786512519&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_71bfa4f7-6d9b-4e88-ab5e-1cdbc4707898.jpg?v=1786512519&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
