INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-slip-on-school-shoe-wv593-black', 'Kids Slip-On School Shoe - WV593 Black', 'WALKAROO', 'SCHOOL', 'Ensure your little girl''s feet are ready for every school day adventure with the WALKAROO Girls'' Slip-On School Shoes. Designed with both practicality and comfort in mind, these shoes are the perfect companion for her bustling schedule, from classroom learning to playground fun. Crafted to be exceptionally lasting and durable, they can withstand the rigors of daily wear and tear, ensuring that they remain a reliable part of her uniform throughout the school year. The sturdy construction and high-quality materials mean you won''t have to worry about constant replacements, saving you time and money. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 219.0, 275.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_19fa1d9b-8c22-4fb4-afa5-80f0be07701a.jpg?v=1786512011&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_19fa1d9b-8c22-4fb4-afa5-80f0be07701a.jpg?v=1786512011&width=1920"]'::jsonb, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
