INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgr53156-black', 'Men''s Daily Wear Sandals - WGR53156 Black', 'WALKAROO', 'Sandals', 'Step into the ultimate blend of comfort and rugged style with the Walkaroo Men''s Black Daily Wear Sandals. Designed for the dynamic man, these sandals offer a secure fit and a powerful look, making them an ideal choice for any casual adventure. The sleek Black color and robust design are complemented by a focus on superior foot comfort.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('girls-daily-wear-sandals-wlp72084-dusty-rose', 'Girl''s Daily Wear Sandals - WLP72084 Dusty Rose', 'WALKAROO PLUS', 'Sandals', 'Step into stylish comfort with the Walkaroo Girls’ WLP72084 Dusty Rose Sandal. Designed for girls who love fashionable and comfortable footwear, this sandal combines a trendy Cross-strap design, attractive printed straps, and a comfortable cushioned sole. Its elegant Dusty Rose colour and dual-tone finish make it a stylish choice for everyday wear, casual outings, and family occasions.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wl7877-purple', 'Women''s Daily Wear Sandals  - WL7877 Purple', 'WALKAROO', 'Sandals', 'Step into effortless style and comfort with the Walkaroo Women''s WL7877 Daily Wear Sandal. This sandal combines modern design and superior comfort, designed for women who want a chic yet comfortable option for everyday wear.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandal-wlp71255-black', 'Women''s Daily Wear Sandal -WLP71255 Black', 'WALKAROO PLUS', 'Sandals', 'Step into everyday comfort and effortless style with the Walkaroo Women''s WLP71255 Black Sandal. Designed for women who prefer a simple yet stylish everyday sandal, this model combines a classic thong-style silhouette with a comfortable cushioned footbed and a contemporary dual-tone sole. It is suitable for daily wear, casual outings, shopping, travel, relaxed walks, and home use.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('men-sports-sandals-wgr15021-black', 'Men Sports Sandals - WGR15021 Black', 'WALKAROO', 'SANDALS', 'Step into comfortable everyday style with the Walkaroo Men''s WGR15021 Black Sandal. Designed for men who prefer a secure fit, supportive construction, and versatile casual styling, this sandal is a practical choice for daily wear, walking, travel, errands, shopping, and casual outdoor use.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoe-ws9104-dark-grey', 'Sports Shoes for Men: Running & Training', 'Walkaroo', 'Footwear', 'Shop men''s sports shoes at Walkaroo. Lightweight running, training and walking shoes with cushioned soles and breathable uppers. Order online now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
