INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgp53410-tan', 'Men''s Daily Wear Sandals - WGP53410 Tan', 'URBANOZ', 'Sandals', 'Experience premium comfort and modern casual styling with the Walkaroo Urbanoz WGP53410 Tan Comfort Sandal . Designed for men who appreciate superior comfort and effortless versatility, this sandal combines a soft PU upper, adjustable fit, and lightweight cushioning to keep you comfortable throughout the day. Ideal for daily wear, travel, indoor use, weekend outings, and relaxed outdoor activities, it delivers a perfect balance of function and style.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoe-ws9132-white', 'Men''s Lace-up Sports Shoes - WS9132 White', 'WALKAROO SPORTZ', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 978.0, 999.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_2cd2ba95-8343-4567-9878-ef77f733fbf3.jpg?v=1786513092&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_2cd2ba95-8343-4567-9878-ef77f733fbf3.jpg?v=1786513092&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgp53510-brown', 'Men''s Daily Wear Sandals - WGP53510 Brown', 'WALKAROO PLUS', 'Sandals', 'Walkaroo Men’s WGP53510 Brown Dual-Tone Sandal is designed for men who prefer a combination of everyday comfort, smart casual styling, and easy wearability. Featuring a sleek Brown upper with a contrasting light-coloured sole, this sandal offers a versatile look suitable for daily outings, casual occasions, shopping, travel, and regular everyday use.
