INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-clogs-wc8710-dark-grey', 'Clogs for Men – EVA Clogs & Slippers ₹249+', 'Walkaroo', 'Footwear', 'Shop men''s clogs that are water-friendly, lightweight & easy to clean. Starting ₹249. Made in India. Free shipping & COD available.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-slip-on-casual-shoes-wlr19999-black', 'Women''s Slip-on Casual Shoes - WLR19999 Black', 'WALKAROO PLUS', 'Flats', 'Step into effortless everyday comfort and modern casual style with the Walkaroo WLR19999 Black Ladies Slip-On Shoe. Designed for women who prefer lightweight and easy-to-wear footwear, this shoe features a stylish knitted upper, convenient slip-on construction, and a comfortable everyday design. It is ideal for daily wear, casual outings, shopping, travel, college, errands, and light walking.
