INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sandals-we1332-beige', 'Sandals for Men - Shop Stylish Men Sandals Online in India', 'Walkaroo', 'Footwear', 'Shop premium sandals for men online starting at ₹239 at Walkaroo. Explore stylish, durable, and comfortable mens sandals, including classic and modern slip-on sandals for everyday wear.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-kids-formals-shoes-wv551-black', 'Kids Slip-On School Shoes - WV551 Black', 'WALKAROO', 'SCHOOL', 'Ensure your little girl''s feet are ready for every school day adventure with the WALKAROO Girls'' Slip-On School Shoes. Designed with both practicality and comfort in mind, these shoes are the perfect companion for her bustling schedule, from classroom learning to playground fun. Crafted to be exceptionally lasting and durable, they can withstand the rigors of daily wear and tear, ensuring that they remain a reliable part of her uniform throughout the school year. The sturdy construction and high-quality materials mean you won''t have to worry about constant replacements, saving you time and money. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt. Note: Kindly purchase footwear size 1/2 cm more than your kid''s foot size.', 239.0, 259.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/03_b57960fe-d0f5-49c8-9810-171f14dafde3.jpg?v=1786513125&width=1920', '["https://www.walkaroo.in/cdn/shop/files/03_b57960fe-d0f5-49c8-9810-171f14dafde3.jpg?v=1786513125&width=1920"]'::jsonb, 6) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandal-wlr71251-crushed-berry', 'Women''s Daily wear Sandal - WLR71251 Crushed Berry', 'WALKAROO', 'Slippers', 'Step into effortless style and everyday comfort with the Walkaroo Women''s WLR71251 Crushed Berry Daily Wear Sandal. Designed for women who prefer comfortable and easy-to-wear footwear, this sandal combines a stylish toe-post design, decorative strap detailing, and a comfortable Cushion Sole, making it suitable for daily wear and casual occasions.
