INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-dailywear-sliders-wk727-blue', 'Kid''s Dailywear Sliders - WK727 Blue', 'WALKAROO', 'Slippers', 'Made for everyday comfort and cute style, the Walkaroo WK727 kids’ slider features a soft cushion sole and a secure single strap with toe loop that keeps little feet comfortably in place. Lightweight and easy to slip on, it’s a cheerful pick for playtime, park strolls and casual outings.
