INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('girls-daily-wear-sandals-wlp72084-espresso', 'Girl''s Daily Wear Sandals - WLP72084 Espresso', 'WALKAROO PLUS', 'Sandals', 'Step into stylish comfort with the Walkaroo Girls’ WLP72084 Espresso Sandal. Designed for girls who love fashionable and comfortable footwear, this sandal combines a trendy Cross-strap design, attractive printed straps, and a comfortable cushioned sole. Its elegant Espresso colour and dual-tone finish make it a stylish choice for everyday wear, casual outings, and family occasions.
