INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-xs9771-black-mint', 'Walkaroo Men Walking and Washable Shoes - XS9771 Black Mint', 'WALKAROO', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 889.0, 889.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/3_345804ac-066f-471c-b4b1-a650dd0cd4ad.jpg?v=1786513754&width=1920', '["https://www.walkaroo.in/cdn/shop/files/3_345804ac-066f-471c-b4b1-a650dd0cd4ad.jpg?v=1786513754&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-womens-sandals-wl7581-beige', 'Women''s Daily Wear Sandals  - WL7581 Beige', 'WALKAROO', 'Sandals', 'WALKAROO Women’s Daily Wear Sandal (WL7581) in Beige is designed for everyday comfort with a smart and stylish look. Made for women who want easy slip-on wear, dependable cushioning, and a modern double-strap design, this sandal is a practical choice for daily use, casual outings, shopping, and relaxed day-to-day wear.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-lace-up-sports-shoe-ws9917-peach-sky', 'Sports Shoes for Women: Running & Gym', 'Walkaroo', 'Footwear', 'Shop women''s sports shoes at Walkaroo. Lightweight, breathable running and gym shoes with cushioned soles. Find your perfect pair and order now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-daily-wear-sandal-wkp80001-blue', 'Kid''s Daily Wear Sandal  - WKP80001 Blue', 'WALKAROO PLUS', 'Sandals', 'Built for everyday adventures, the Walkaroo WKP80001 Kids’ Blue Sandals combine durable construction with all-day comfort. The open-toe, open-heel design keeps feet airy, while the soft, supportive cushion sole helps reduce fatigue during play, school runs, and weekend outings.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-formals-shoes-wf6052-black', 'Men''s Leather formals Shoes - WF6052 Black', 'WALKAROO', 'SHOES', 'Meet our new lineup of men''s formal shoes, crafted for comfort. The new lineup of leather shoes crafted from high-quality leather offers both comfort and style. perfected for the professionals in you.Care instructions:To remove dirt or surface residue, use a soft damp cloth. Gently rub for removal. For a deeper clean, use a leather cleaner to help preserve the natural smooth oils instead of stripping them.To prevent the leather from losing suppleness over time use a wax-free leather conditioner that will nourish and restore the flexibility and suppleness of your leather goodiesLeather is a natural material, please, store your leather Shoes in a breathable, non-plastic container to prevent the growth of bacteria and mildew.', 1030.0, 1030.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/3_d738b21a-90e7-4e51-81ee-313238b5a5c5.jpg?v=1786513745&width=1920', '["https://www.walkaroo.in/cdn/shop/files/3_d738b21a-90e7-4e51-81ee-313238b5a5c5.jpg?v=1786513745&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-flip-flop-sliders-502-aqua-blue', 'Men''s Slides - 502 Aqua Blue', 'ME&I', 'Slippers', 'Step into casual comfort and effortless style with the Walkaroo Men''s 502 Aqua Blue Slider. Perfectly designed as a lightweight slider for men, this footwear combines ease of wear with daily comfort, making it ideal for home, errands, or casual outdoor activities.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-clogs-wc4849-light-grey', 'Walkaroo - Men''s, Women''s & Kid''s Footwear | India''s No.1 PU Brand', 'Walkaroo', 'Footwear', 'Buy footwear online from India''s No.1 PU footwear brand at an affordable price. Walkaroo offers a wide range of footwear for Men, Women, and Kids, including shoes, flip-flops, sandals, sliders, heels, and flats. Shop now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgp53410-brown', 'Men''s Daily Wear Sandals - WGP53410 Brown', 'URBANOZ', 'Sandals', 'Step into everyday comfort and effortless style with the Walkaroo Urbanoz WGP53410 Brown Comfort Sandal. Designed for men who value comfort, support, and easy everyday wear, this sandal features a practical dual-strap design with adjustable hook-and-loop closures, an ergonomic footbed, heel support, and a lightweight construction. It is an ideal choice for daily wear, casual outings, travel, shopping, and relaxed outdoor activities.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-ws9507-black', 'Sports Shoes for Men: Running & Training', 'Walkaroo', 'Footwear', 'Shop men''s sports shoes at Walkaroo. Lightweight running, training and walking shoes with cushioned soles and breathable uppers. Order online now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('boys-sports-sandals-wg5782-blue-grey', 'Boys Sports Sandals - WG5782 Blue Grey', 'WALKAROO', 'SANDALS', 'This Toe Ring style from Walkaroo gives a very classy look & a very good grip. The PU sole from Walkaroo makes it light weight, durable & gives a firm grip. You can wear these Walkaroo pair on your ethnic occasion. Pair it with your Dhoti or any other traditional wear. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust.', 429.0, 429.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WG5782-BLUEGREY-BOYS_jpg_379f454d-44f8-4b0d-a14a-d62f27a6c404.jpg?v=1786511354&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WG5782-BLUEGREY-BOYS_jpg_379f454d-44f8-4b0d-a14a-d62f27a6c404.jpg?v=1786511354&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
