INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-women-casual-shoes-wc4985-grey', 'Walkaroo Womens Textured Belly Shoes - WC4985 Grey', 'WALKAROO', 'SHOES', 'These BellyshoesÂ from Walkaroo are a flat slipper type shoe best for those who want something to wear anywhere. These versatile shoes come in many prints, colours and patterns. They look great with a maxi dress, leggings or jeans & a T-shirt for a quick and simple weekend outfit. Printed Bellyshoes can also be styled with shorts for a sunny weekend. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 399.0, 399.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/03_e56c8730-a84f-47a9-9249-3b008129a254.jpg?v=1786513759&width=1920', '["https://www.walkaroo.in/cdn/shop/files/03_e56c8730-a84f-47a9-9249-3b008129a254.jpg?v=1786513759&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-trekking-shoe-sge21001-olive-black', 'Men''s Trekking Shoe - SGE21001 Olive Black', 'WALKAROO SPORTZ', 'Athletic Shoes', 'Embark on any adventure with confidence in the Walkaroo Sportz SGE21001 Olive Black Men''s Off-Road Adventure Shoe. Designed as a robust trekking shoe, it offers the perfect blend of durability, comfort, and advanced features for your outdoor pursuits.
