INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-womens-clogs-wc8912-baby-pink', 'Walkaroo Womens Clogs  - WC8912 Baby Pink', 'WALKAROO', 'Slippers', 'These Clogs from Walkaroo are typically worn as a casual wear. They have a flat sole held on the foot by a toe thong which gives you good grip. They can be worn indoors or outdoors. Match it with your pajamas, sweatpants, hoodies,etc. And with the flip flop day outfits like the long dress, denim skirt or all black denim look, plays up the colourful Clogs. Try to keep the look as monochromatic as possible and play with proportions i.e., flowing bottoms &amp; tight top. Care instructions: Minimal care, no maintenance needed.', 345.0, 349.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_1521af48-b2e5-411c-b5b7-25af392e8b44.jpg?v=1786513078&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_1521af48-b2e5-411c-b5b7-25af392e8b44.jpg?v=1786513078&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
