INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-flip-flops-wc4240-navy-blue', 'Shop Men''s Sandals & Flip-Flops Online at Best Prices', 'Walkaroo', 'Footwear', 'Shop men’s sandals & flip-flops online in India at Walkaroo. Explore lightweight, cushioned & durable styles perfect for everyday comfort and casual wear.', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-chelsea-boots-wgp26706-black', 'Men''s Chelsea Boots - WGP26706 Black', 'WALKAROO PLUS', 'Shoes', 'Define your everyday style with the Walkaroo Men''s WGP26706 Black Chelsea Boots. Designed with a refined suede upper, stretchable side panels, and a durable TPR sole, these ankle-length boots combine smart styling with convenient slip-on wear.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wc8764-brown-tan', 'Men''s Daily Wear Sandals - WC8764 Brown Tan', 'FLIP-FLOPZ+', 'Sandals', 'Step into the perfect blend of comfort, style, and adjustability with the Walkaroo Men''s WC8764 Brown Tan Sandal. Designed for casual daily wear, this contemporary two-strap sandal promises "All Day Comfort" and an exceptionally "SOFT" feel.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-lace-up-sports-shoes-ws9640-navy-blue', 'Men''s Lace-up Sports Shoes - WS9640 Navy Blue', 'WALKAROO SPORTZ', 'Athletic Shoes', 'Step into effortless style and comfort with the Walkaroo Men''s WS9640 Navy Blue Sports Shoes. Designed for easy daily wear and light activities, these sports shoes feature a breathable mesh upper that provides a lightweight, sock-like fit with supportive synthetic overlays. The classic lace-up closure ensures a secure and adjustable fit. Built with a durable TPR (Thermoplastic Rubber) sole, these shoes deliver stable traction and flexibility for all-day comfort. The sculpted sole design adds a dynamic look, making them a perfect addition to your casual and active wardrobe.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('saigo-mens-lace-up-sports-shoe-ws9158-blue-orange', 'SAIGO Men''s Lace-up Sports Shoes - WS9158 Blue Orange', 'WALKAROO SPORTZ', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 1155.0, 1299.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_bb62b168-45f9-49ab-a913-a0b2d48e8e3a.jpg?v=1786512623&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_bb62b168-45f9-49ab-a913-a0b2d48e8e3a.jpg?v=1786512623&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-hawai-slippers-hg193-grey', 'Men''s Slippers Online – Comfortable Flip Flops & Slides', 'Walkaroo', 'Footwear', 'Shop men''s slippers online at Walkaroo. Soft, lightweight and durable slippers for home and daily wear, starting at ₹199. Free shipping/COD. Order now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-slippers-fgr14300-olive-tan', 'Men''s Flip-Flops -FGR14300 Olive Tan', 'WALKAROO', 'Slippers', 'Step into everyday comfort and casual style with the Walkaroo Gents FGR14300 Olive Tan Flip-Flops. Designed for men who prefer lightweight and easy-to-wear footwear, these flip-flops are ideal for daily use, home wear, casual outings, travel, beach visits, and relaxed outdoor activities.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wlp74065-olive', 'Women''s Daily Wear Sandals - WLP74065 Olive', 'WALKAROO PLUS', 'Sandals', 'Step into stylish everyday comfort with the Walkaroo Women''s WLP74065 Olive Daily Wear Sandal. Designed for women who prefer a blend of contemporary styling and comfortable everyday footwear, this sandal features a fashionable double-strap design, metallic buckle detailing, a dual-tone finish, and a Cushion Sole for regular use.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandal-wlr70439-espresso', 'Women''s Daily wear Sandal - WLR70439 Espresso', 'WALKAROO', 'Slippers', 'Step into effortless style and comfort with the Walkaroo Women''s WLR70439 Espresso Daily Wear Sandal. Designed for everyday ease, this lightweight sandal combines a versatile design with an extra cushioned footbed, making it suitable for daily wear, casual outings, shopping, travel, errands, and relaxed everyday activities.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-womens-care-plus-flip-flop-wh3951-blue', 'Women''s Care Plus Flip-Flop  - WH3951 Blue', 'WALKAROO CARE PLUS', 'Sandals', 'Experience the perfect blend of comfort and style in every step! Designed with cushioned support and a trendy look, our footwear brings ease to your stride while keeping you fashion-forward. Slip into a pair that complements both your active lifestyle and your sense of style', 249.0, 259.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WH3951-BLUE_6387f689-2717-4136-bccb-58c0524c43fd.jpg?v=1786512713&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WH3951-BLUE_6387f689-2717-4136-bccb-58c0524c43fd.jpg?v=1786512713&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
