INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-comfort-sandals-wlp72051-dusty-rose', 'Women''s Daily Wear Comfort Sandals  - WLP72051 Dusty Rose', 'CLASSICO', 'Sandals', 'Meet the Walkaroo Classico Women’s Cross-Strap Platform Sandal (WLP72051) in a soft, stylish Dusty Rose—made to look elegant and feel easy from morning to night. With a synthetic leather upper, a cushioned PU footbed, and a durable PU sole with slip-resistant grip, this slip-on sandal is built for daily wear, office comfort, casual outings, and travel.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('men-sports-sandals-wg5782-camel', 'Men Sports Sandals - WG5782 Camel', 'WALKAROO', 'SANDALS', 'Experience enhanced comfort and outdoor-ready performance with the Walkaroo Men''s WG5782 Camel Sports Sandal. Designed for men who prefer durable and supportive footwear for active daily use, this sandal combines an adjustable strap system, sporty multi-layer design, Cushion Sole comfort, and a lightweight PU outsole for all-day convenience.
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-ws9119-white-blue', 'Sports Shoes for Men: Running & Training', 'Walkaroo', 'Footwear', 'Shop men''s sports shoes at Walkaroo. Lightweight running, training and walking shoes with cushioned soles and breathable uppers. Order online now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
