INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-ws9122-black-red', 'Sports Shoes for Men: Running & Training', 'Walkaroo', 'Footwear', 'Shop men''s sports shoes at Walkaroo. Lightweight running, training and walking shoes with cushioned soles and breathable uppers. Order online now!', 0.0, 0.0, 'INR', False, '', '[]'::jsonb, 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
